mapper.insert:
insert into delivery (
    job_id, user_id, resume_id, status, status_remark,
    delivery_time, create_time, update_time
) values (
    #{jobId}, #{userId}, #{resumeId}, #{status}, #{statusRemark},
    #{deliveryTime}, #{createTime}, #{updateTime}
)

mapper.select:
select from delivery d left join job j on j.id = d.job_id left join company c on c.id = j.company_id left join resume r on r.id = d.resume_id where d.user_id = #{userId}
and d.status = #{status}
order by d.delivery_time desc

select 
from delivery d
left join job j on j.id = d.job_id
left join company c on c.id = j.company_id
left join resume r on r.id = d.resume_id
inner join `user` u on u.id = d.user_id and u.status = 1
where j.hr_id = #{hrId}

    and d.job_id = #{jobId}


    and d.status = #{status}

order by d.delivery_time desc

mapper.update:
update delivery
status = #{status}, status_remark = #{statusRemark}, view_time = #{viewTime}, interview_time = #{interviewTime}, offer_time = #{offerTime}, update_time = #{updateTime},
